/* lista do "Novo cartão": maiores bancos/cartões e contas de câmbio; toque preenche nome e cor */
const BANK_PICK=["Nubank","Itaú","Bradesco","Banco do Brasil","Caixa","Santander","Inter","C6","Mercado Pago","PicPay","PagBank","BTG","XP","Neon","Pan","Renner"];
const FX_PICK=["Wise","Nomad","ARQ","Revolut"];
const ALL_BANKS=()=>[...new Set([...credCards(),...BANK_PICK,...FX_PICK])];
/* banco/conta de câmbio a partir do "Onde" de uma compra (ex.: "Revolut app" → "Revolut") */
const fxPlaceBank=w=>{const bk=bankOf(w);return bk?[...FX_PICK,...BANK_PICK].find(n=>bankOf(n)===bk)||null:null};
/* onde está o dinheiro da caixinha: o banco escolhido, ou (sem escolha e somando a aba Moedas) os bancos onde comprou */
/* bancos de uma caixinha (20/10/2026, pedido dele: dinheiro em vários bancos): o principal, os de cada movimento que ainda tem saldo
   e, com fxAll, onde as compras de moeda foram feitas */
const svFxBanks=b=>b.fxAll?[...new Set(fx.filter(x=>fxCurOf(x)===boxFx(b)).map(x=>fxPlaceBank(x.where)).filter(Boolean))]:[];
const boxBanks=b=>[...new Set([...(b.bank?[b.bank]:[]),...svBankRows(b).filter(r=>r.bank&&r.pos).map(r=>r.bank),...svFxBanks(b)])];
const bankOf=n=>{const t=(n||"").trim().toLowerCase();return t?BANKS.find(b=>b.m.test(t))||null:null};
const cardLabel=c=>{const b=bankOf(c);if(b)return b.l;const w=(c||"?").trim().split(/\s+/)[0];return w.length<=5?w:w.slice(0,3)};
