function bankLogoSvg(c){
  const b=bankOf(c);
  return (b && b.id && BANK_LOGOS[b.id]) || null;
}
function cardBadge(c){
  const col=cardColor(c), l=cardLabel(c), dark=lumHex(col)>.5, fs=l.length<=2?1:l.length===3?.88:l.length===4?.76:.66;
  const svg=bankLogoSvg(c);
  return `<span class="fi" style="background:${col};color:${dark?"#1A1A1A":"#fff"};--k:${fs}">${svg||esc(l)}</span>`;
}
const CARD_PALETTE=["#8A05BE","#E8730C","#2C6BD6","#C8102E","#0F8F6C","#1F1F1F","#D4A017","#6B7A75"];
const cardColor=c=>((cfg.cards||{})[c]||{}).color||CARD_COLOR[c]||(bankOf(c)||{}).c||"#6B7A75";
/* tela do cartão e importação ficam na cor do cartão (no lugar do verde), ajustada para dar contraste no claro e no escuro */
const hexRgb=h=>{h=(h||"").replace("#","");if(h.length===3)h=h.replace(/./g,"$&$&");const n=parseInt(h,16);return isNaN(n)?[107,122,117]:[n>>16&255,n>>8&255,n&255]};
const mixHex=(h,t,k)=>{const a=hexRgb(h),b=hexRgb(t);return "#"+a.map((v,i)=>Math.round(v+(b[i]-v)*k).toString(16).padStart(2,"0")).join("")};
const lumHex=h=>{const[r,g,b]=hexRgb(h).map(v=>{v/=255;return v<=.03928?v/12.92:((v+.055)/1.055)**2.4});return .2126*r+.7152*g+.0722*b};
const isDark=()=>{const t=document.documentElement.dataset.theme;return t?t==="dark":matchMedia("(prefers-color-scheme: dark)").matches};
/* logo em foto vira transparente: o fundo (cor do canto) é apagado, então some o "quadrado" e o degradê do cartão passa por trás */
const LK={};
function dcKeyAll(){
  document.querySelectorAll("img[data-lk]").forEach(im=>{
    const k=im.dataset.lk; if(LK[k]){if(im.src!==LK[k])im.src=LK[k];return}
    if(im.dataset.busy)return; im.dataset.busy=1;
    const go=()=>{try{
      const W=im.naturalWidth,H=im.naturalHeight; if(!W)return;
      const c=document.createElement("canvas");c.width=W;c.height=H;const g=c.getContext("2d");g.drawImage(im,0,0);
      const d=g.getImageData(0,0,W,H),a=d.data,r0=a[0],g0=a[1],b0=a[2];
      for(let i=0;i<a.length;i+=4){const dist=Math.abs(a[i]-r0)+Math.abs(a[i+1]-g0)+Math.abs(a[i+2]-b0);a[i+3]=Math.min(255,Math.max(0,(dist-24)*4))*(a[i+3]/255)}
      g.putImageData(d,0,0);LK[k]=c.toDataURL("image/png");document.querySelectorAll(`img[data-lk="${k}"]`).forEach(x=>x.src=LK[k]);
    }catch(e){}};
    if(im.complete)go();else im.addEventListener("load",go,{once:true});
  });
}
const DCL_SCALE={inter:1.75,mp:1.3,renner:1.0,xp:1.0};
function dcLogo(c){
  const b=bankOf(c), svg=bankLogoSvg(c);
  if(!svg) return `<span class="dclogo lt">${esc(cardLabel(c))}</span>`;
  const sc=b&&DCL_SCALE[b.id]||1; let h=svg.startsWith("<img")?svg:svg.replace("<svg ",'<svg preserveAspectRatio="xMinYMid meet" ');
  if(svg.startsWith("<img")&&b) h=h.replace("<img ",`<img data-lk="${b.id}" `);
  return `<span class="dclogo" style="--ls:${sc}">${h}</span>`;
}
